{"description":"Fetch yesterday's BTC price from CoinGecko and store in btc_prices","id":"daily_btc","schedule":"0 8 * * *","steps":"fetch https://api.coingecko.com/api/v3/coins/bitcoin/history?date={{yesterday_ddmmyyyy}}
parse json $.market_data.current_price.usd as close
parse json $.market_data.total_volumes[0][1] as volume
set open = close
insert into btc_prices (date, open, close, volume) values ({{yesterday_date}}, {{open}}, {{close}}, {{volume}})"}

{"description":"Fetch yesterday's BTC price from CoinGecko in EUR and store in btc_prices (prices in EUR)","id":"daily_btc","schedule":"0 8 * * *","steps":"fetch https://api.coingecko.com/api/v3/coins/bitcoin/history?date={{yesterday_ddmmyyyy}}
parse json $.market_data.current_price.eur as close_eur
