{"description":"Fetch yesterday's ETH price from CoinGecko in EUR and store in eth_prices (prices in EUR)","id":"daily_eth","schedule":"0 7 * * 1-5","steps":"fetch https://api.coingecko.com/api/v3/coins/ethereum/history?date={{yesterday_ddmmyyyy}}
parse json $.market_data.current_price.eur as close_eur
