{"description":"Check BTC and ETH price drops >5% and send alert to Telegram","id":"price_alert","schedule":"0 8 * * 1-5","steps":"query SELECT date, close FROM btc_prices ORDER BY date DESC LIMIT 2 INTO btc_last2;
query SELECT date, close FROM eth_prices ORDER BY date DESC LIMIT 2 INTO eth_last2;
calculate btc_change = (btc_last2[0].close - btc_last2[1].close) / btc_last2[1].close * 100;
calculate eth_change = (eth_last2[0].close - eth_last2[1].close) / eth_last2[1].close * 100;
if btc_change < -5 then telegram_send "BTC price dropped {btc_change:.2f}% on {btc_last2[0].date}";
if eth_change < -5 then telegram_send "ETH price dropped {eth_change:.2f}% on {eth_last2[0].date}";"}

{"description":"Fetch yesterday's Bitcoin price from CoinGecko and insert into btc_prices","id":"daily_btc","schedule":"0 8 * * *","steps":"[
  {"type":"http_get","url":"https://api.coingecko.com/api/v3/coins/bitcoin/history?date={{yesterday}}","output":"price_data"},
  {"type":"transform","input":"price_data","script":"let d = new Date(); d.setDate(d.getDate()-1); let date = d.toISOString().split('T')[0]; let market = price_data.market_data; return {date: date, open: market.current_price.usd, close: market.current_price.usd, volume: market.total_volume.usd};","output":"row"},
  {"type":"insert","table":"btc_prices","rows":"row"}
]"}

